class Solution {
public:
    int findKthPositive(vector<int>& arr, int k) {

        int count = 0;
        int j = 0, i = 1;

        for(i = 1; i < arr[arr.size() - 1]; i++){

            if(i != arr[j])
                count++;

            else
                j++;

            if(count == k)
                return i;

        }

        if(count < k)
            return i + k - count;

        return 0;
    }
};

package task_1539;

public class Solution {

    public int findKthPositive(int[] arr, int k) {
        int[] missedItems = new int[k];
        int missedItemIndex = 0;
        int missedItem = 1;
        int maximum = arr[arr.length - 1];
        for (int i = 0; i < arr.length; i++) {
            while (missedItem < arr[i]) {
                missedItems[missedItemIndex] = missedItem;
                missedItemIndex++;
                missedItem++;
                if (missedItemIndex == k) {
                    return missedItems[k - 1];
                }
            }
            missedItem++;
        }
        while (missedItemIndex < k) {
            if (missedItem > maximum) {
                missedItems[missedItemIndex] = missedItem;
                maximum = missedItem;
                missedItemIndex++;
                if (missedItemIndex == k) {
                    return missedItems[k - 1];
                }
            }
            missedItem++;
        }
        return missedItems[0];
    }

}

//Approach 1: Using linear search technique. TC: O(n) SC: O(1)
//Editorial: https://leetcode.com/problems/kth-missing-positive-number/discuss/1004517/C%2B%2B-2-LINER-SIMPLEST!!-O(n)-time-O(1)-space-faster-than-99
class Solution {
public:
    int findKthPositive(vector<int>& arr, int k) {
        for(auto it:arr)
        {
            if(it<=k)
                k+=1;
        }
        return k;
    }
};
//Approach 2: Using Binary search. TC: O(logn) SC: O(1)
//Editorial: https://leetcode.com/problems/kth-missing-positive-number/discuss/1004437/C%2B%2B-Optimized-Solution-with-Detailed-Explanation-C%2B%2B-100Faster-0-ms
class Solution {
public:
    int findKthPositive(vector<int>& arr, int k) {
        int n=arr.size();
        int low=0,high=n-1;
        while(low<=high)
        {
            int mid=low+(high-low)/2;
            if(arr[mid]-(mid+1)<k)
                low=mid+1;
            else
                high=mid-1;
        }
        return low+k;
    }
};
